//! Saved sessions on disk: one JSON file per session in `history/`.

use std::path::{Path, PathBuf};

use super::model::{FORMAT_VERSION, HistorySession, HistorySummary};

pub struct HistoryStore {
    dir: PathBuf,
}

/// Session ids are generated by the app: digits, `a-f` and `-`. Anything
/// else (e.g. `../`) is refused before touching the disk.
pub fn is_valid_id(id: &str) -> bool {
    !id.is_empty()
        && id.len() <= 64
        && id
            .chars()
            .all(|c| c.is_ascii_digit() || ('a'..='f').contains(&c) || c == '-')
}

impl HistoryStore {
    pub fn new(dir: PathBuf) -> Self {
        Self { dir }
    }

    pub fn path(&self, id: &str) -> Option<PathBuf> {
        is_valid_id(id).then(|| self.dir.join(format!("{id}.json")))
    }

    /// Writes a session atomically (temporary file, then rename), so a
    /// crash never leaves a half-written file.
    pub fn save(&self, session: &HistorySession) -> std::io::Result<()> {
        let path = self.path(&session.id).ok_or_else(invalid_id)?;
        std::fs::create_dir_all(&self.dir)?;
        let tmp = path.with_extension("json.tmp");
        std::fs::write(&tmp, serde_json::to_vec(session)?)?;
        std::fs::rename(tmp, path)
    }

    pub fn load(&self, id: &str) -> std::io::Result<HistorySession> {
        let path = self.path(id).ok_or_else(invalid_id)?;
        read(&path)
    }

    /// Summaries of every readable session, newest first. Unreadable files
    /// are skipped (and logged).
    pub fn list(&self) -> std::io::Result<Vec<HistorySummary>> {
        let entries = match std::fs::read_dir(&self.dir) {
            Ok(entries) => entries,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
            Err(error) => return Err(error),
        };
        let mut summaries: Vec<HistorySummary> = entries
            .filter_map(Result::ok)
            .map(|entry| entry.path())
            .filter(|path| path.extension().is_some_and(|ext| ext == "json"))
            .filter_map(|path| match read(&path) {
                Ok(session) => Some(session.summary()),
                Err(error) => {
                    log::warn!("skipping history file {}: {error}", path.display());
                    None
                }
            })
            .collect();
        summaries.sort_by(|a, b| b.started_at.total_cmp(&a.started_at));
        Ok(summaries)
    }

    pub fn delete(&self, id: &str) -> std::io::Result<()> {
        let path = self.path(id).ok_or_else(invalid_id)?;
        match std::fs::remove_file(path) {
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
            other => other,
        }
    }

    /// Deletes every saved session.
    pub fn clear(&self) -> std::io::Result<()> {
        match std::fs::remove_dir_all(&self.dir) {
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
            other => other,
        }
    }
}

fn read(path: &Path) -> std::io::Result<HistorySession> {
    let session: HistorySession = serde_json::from_slice(&std::fs::read(path)?)?;
    if session.version != FORMAT_VERSION {
        return Err(std::io::Error::other(format!(
            "unsupported history format {}",
            session.version
        )));
    }
    Ok(session)
}

fn invalid_id() -> std::io::Error {
    std::io::Error::new(std::io::ErrorKind::InvalidInput, "invalid session id")
}

#[cfg(test)]
mod tests {
    use super::super::model::tests::{segment, session};
    use super::*;

    /// A folder under the system temp dir, removed when dropped.
    struct TempDir(PathBuf);

    impl Drop for TempDir {
        fn drop(&mut self) {
            let _ = std::fs::remove_dir_all(&self.0);
        }
    }

    fn temp_store() -> (TempDir, HistoryStore) {
        let dir = TempDir(std::env::temp_dir().join(format!(
            "esperanto-history-test-{}",
            crate::util::random_hex(8)
        )));
        let store = HistoryStore::new(dir.0.join("history"));
        (dir, store)
    }

    #[test]
    fn saves_lists_loads_and_deletes() {
        let (_dir, store) = temp_store();
        assert!(store.list().unwrap().is_empty());

        let mut older = session(vec![segment(0.0, 1_000.0, "Older.")]);
        older.id = "100-aa".into();
        older.started_at = 100.0;
        let mut newer = session(vec![segment(0.0, 1_000.0, "Newer.")]);
        newer.id = "200-bb".into();
        newer.started_at = 200.0;
        store.save(&older).unwrap();
        store.save(&newer).unwrap();

        let ids: Vec<_> = store.list().unwrap().into_iter().map(|s| s.id).collect();
        assert_eq!(ids, vec!["200-bb", "100-aa"]);
        assert_eq!(store.load("100-aa").unwrap(), older);

        store.delete("100-aa").unwrap();
        store.delete("100-aa").unwrap(); // already gone: fine
        assert_eq!(store.list().unwrap().len(), 1);

        store.clear().unwrap();
        assert!(store.list().unwrap().is_empty());
    }

    #[test]
    fn skips_unreadable_files() {
        let (_dir, store) = temp_store();
        store.save(&session(vec![])).unwrap();
        std::fs::write(store.dir.join("999-ff.json"), b"not json").unwrap();
        assert_eq!(store.list().unwrap().len(), 1);
    }

    #[test]
    fn refuses_ids_that_could_escape_the_folder() {
        assert!(is_valid_id("1795015049473-abcdef"));
        for bad in ["", "../settings", "a/b", "x.json", "ABC"] {
            assert!(!is_valid_id(bad), "{bad}");
        }
        let (_dir, store) = temp_store();
        assert!(store.load("../settings").is_err());
        assert!(store.delete("../settings").is_err());
    }
}
